const listCatalogDataParameters = `-- name: ListCatalogDataParameters :many
;

SELECT id, parent_id, map_key, value FROM athena_catalogs_data_parameters WHERE parent_id = ? ORDER BY map_key
`

func (q *Queries) ListCatalogDataParameters(ctx context.Context, parentID int64) ([]AthenaCatalogsDataParameter, error) {
	rows, err := q.db.QueryContext(ctx, listCatalogDataParameters, parentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AthenaCatalogsDataParameter{}
	for rows.Next() {
		var i AthenaCatalogsDataParameter
		if err := rows.Scan(
			&i.ID,
			&i.ParentID,
			&i.MapKey,
			&i.Value,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

